{
  "steps": [
    {
      "title": "დაკეტე წყალი",
      "text": "მოატრიალე ონკანი საათის ისრის მიმართულებით ბოლომდე. შემდეგ მეორეც დაკეტე.",
      "focus": ["p2", "p3"],
      "avoid": [],
      "markers": [
        {"part": "p2", "label": "პირველი ონკანი", "tone": "brand"},
        {"part": "p3", "label": "მეორე ონკანი", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p2", "type": "rotate", "dir": "cw"},
        {"part": "p3", "type": "rotate", "dir": "cw"}
      ],
      "tools": [],
      "warn": "არ დაატანო ძალა გაჭედილ ონკანს."
    },
    {
      "title": "ჩადგი ვედრო სიფონის ქვეშ",
      "text": "სიფონში წყალი დგას. გახსნისას ჩამოიღვრება, ამიტომ ვედრო ან ღრმა თასი პირდაპირ მის ქვეშ დადგი.",
      "focus": [],
      "avoid": [],
      "markers": [],
      "arrows": [],
      "tools": ["ვედრო ან ღრმა თასი"],
      "warn": "დასადგმელი ვედრო ან თასი ფოტოზე და ნაწილების სიაში არ ჩანს, ამიტომ focus ცარიელია."
    },
    {
      "title": "მოუშვი ქანჩი",
      "text": "ეს ქანჩი ჟონავს. ხელით მოუშვი საათის ისრის საწინააღმდეგოდ. პლასტმასისაა, გასაღები არ დაგჭირდება.",
      "focus": ["p4"],
      "avoid": ["p1"],
      "markers": [
        {"part": "p4", "label": "ქანჩი ხილული წვეთებით", "tone": "brand"},
        {"part": "p1", "label": "ამ ეტაპზე არ შეეხო", "tone": "neutral"}
      ],
      "arrows": [
        {"part": "p4", "type": "rotate", "dir": "ccw"}
      ],
      "tools": [],
      "warn": "ყველაზე სავარაუდო სამიზნეა p4: მარჯვენა ჰორიზონტალურ შეერთებაზე და მის ქვემოთ წვეთები ჩანს. ეს გაჟონვის ზუსტ წყაროს საბოლოოდ არ ადასტურებს. ბრუნვის მიმართულება იგულისხმება ქანჩის ღერძის გასწვრივ შესაბამისი მხრიდან ყურებისას."
    },
    {
      "title": "შეამოწმე შუასადები",
      "text": "მოხსენი სიფონი და ნახე ქანჩის შიგნით რეზინის რგოლი. თუ დაბზარულია ან გვერდზეა გადაწეული, შეცვალე. ზომა: 40 მმ.",
      "focus": ["p5", "p4"],
      "avoid": [],
      "markers": [
        {"part": "p5", "label": "მოსახსნელი სიფონი", "tone": "brand"},
        {"part": "p4", "label": "შუასადები ამ შეერთების შიგნითაა", "tone": "neutral"}
      ],
      "arrows": [],
      "tools": ["შესაბამისი ზომის ახალი შუასადები"],
      "warn": "შუასადები შიგნითაა და ფოტოზე არ ჩანს; p4 აღნიშნავს მის სავარაუდო შეერთებას და არა თავად რგოლს. 40 მმ მოცემული ინსტრუქციის ზომაა და ფოტოთი არ დასტურდება — შეადარე მოხსნილ შუასადებს. სიფონი ძალით არ მოქაჩო; მოხსნამდე გაათავისუფლე მისი დამჭერი შეერთებები."
    },
    {
      "title": "მოუჭირე და შეამოწმე",
      "text": "ხელით მოუჭირე ბოლომდე, შემდეგ კიდევ მეოთხედი ბრუნი. გახსენი წყალი და ერთი წუთი დააკვირდი.",
      "focus": ["p4", "p2", "p3"],
      "avoid": [],
      "markers": [
        {"part": "p4", "label": "მოუჭირე და შეამოწმე გაჟონვა", "tone": "brand"},
        {"part": "p2", "label": "გახსენი წყალი", "tone": "neutral"},
        {"part": "p3", "label": "გახსენი წყალი", "tone": "neutral"}
      ],
      "arrows": [
        {"part": "p4", "type": "rotate", "dir": "cw"},
        {"part": "p2", "type": "rotate", "dir": "ccw"},
        {"part": "p3", "type": "rotate", "dir": "ccw"}
      ],
      "tools": [],
      "warn": "სამიზნედ კვლავ p4 არის მიჩნეული ხილული წვეთების გამო. დამატებითი მეოთხედი ბრუნი უნივერსალური წესი არ არის: არ გადააჭირო პლასტმასს და დაიცავი მწარმოებლის მითითება. შეამოწმე ყველა დაშლილი შეერთება; წყლის ჩამკეტების გახსნის შემდეგ ნიჟარის ონკანიც გაუშვი, რომ სიფონში წყალმა გაიაროს."
    }
  ],
  "unknown_parts": [
    "ვედრო ან ღრმა თასი — ფოტოზე არ ჩანს და ID არ აქვს.",
    "ქანჩის შიგნით არსებული რეზინის შუასადები — დაფარულია და ცალკე ID არ აქვს.",
    "ნიჟარის წყლის გამშვები ონკანი — ფოტოზე არ ჩანს და ID არ აქვს."
  ]
}
